public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    if (nums == null || nums.length == 0) {
        return result;
    }

    doPermute(nums, 0, result);
    return result;
}

private void doPermute(int[] nums, int start, List<List<Integer>> result) {
    if (start == nums.length) {
        result.add(new ArrayList<>(Arrays.asList(nums)));
        return;
    }

    for (int i = start; i < nums.length; i++) {
        // Swap nums[i] and nums[start]
        int temp = nums[i];
        nums[i] = nums[start];
        nums[start] = temp;

        doPermute(nums, start + 1, result);

        // Swap nums[i] and nums[start] back
        temp = nums[i];
        nums[i] = nums[start];
        nums[start] = temp;
    }
}
