        return result;
    }

    permuteRecursive(result, nums, 0, new ArrayList<>());
    return result;
}

private void permuteRecursive(List<List<Integer>> result, int[] nums, int start, List<Integer> permutation) {
    if (start == nums.length) {
        result.add(new ArrayList<>(permutation));
        return;
    }

    for (int i = start; i < nums.length; i++) {
        Collections.swap(permutation, start, i);
        permuteRecursive(result, nums, start + 1, permutation);
        Collections.swap(permutation, start, i);
    }
}
