public int findLargestSubstring(List<String> strings) {
    int maxLength = 1; // Initialize maxLength to 1 because the smallest possible substring is of length 1

    // Iterate through the list of strings
    for (int i = 0; i < strings.size(); i++) {
        String str = strings.get(i);
        // Check for the substring by slicing the string from index i to all possible positions
        for (int j = 0; j <= str.length(); j++) {
            if (checkForSubstring(strings, str.substring(j))) { // Check if any of the given strings contains the substring
                maxLength = Math.max(maxLength, j); // Update maxLength if the substring is found
                break; // Exit the inner loop if we find a valid substring in the current string
            }
        }
    }

    return maxLength; // Return the length of the largest convincing string
}

private boolean checkForSubstring(List<String> strings, String substring) {
    for (String s : strings) {
        if (s.contains(substring) || s.contains(new StringBuilder(substring).reverse().toString())) {
            return true; // Return true if the substring is found in any of the strings
        }
    }
    return false; // Return false if no substring is found
}
