public static int countOilDeposits(char[][] grid) {
    int distinctDeposits = 0;
    boolean[][] visited = new boolean[grid.length][grid[0].length];

    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[i].length; j++) {
            if (grid[i][j] == '@' && !visited[i][j]) {
                distinctDeposits++;
                explore(grid, visited, i, j);
            }
        }
    }

    return distinctDeposits;
}

private static void explore(char[][] grid, boolean[][] visited, int row, int col) {
    if (row < 0 || col < 0 || row >= grid.length || col >= grid[row].length || grid[row][col] != '@' || visited[row][col]) {
        return;
    }

    visited[row][col] = true;

    explore(grid, visited, row + 1, col);
    explore(grid, visited, row - 1, col);
    explore(grid, visited, row, col + 1);
    explore(grid, visited, row, col - 1);
}
