public static int countOilDeposits(char[][] grid) {
    int rows = grid.length;
    int cols = grid[0].length;
    int OilCount = 0;

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (grid[i][j] == '@') {
                // Flood fill starting from the oil pocket
                floodFill(grid, i, j, OilCount);
                OilCount++;
            }
        }
    }

    return OilCount;
}

private static void floodFill(char[][] grid, int r, int c, int oilCount) {
    int rows = grid.length;
    int cols = grid[0].length;
    if (r < 0 || c < 0 || r >= rows || c >= cols || grid[r][c] != '@') {
        return;
    }
    grid[r][c] = '-'; // Mark as visited
    oilCount++; // Increment the oil count

    // Recursively flood the adjacent cells
    floodFill(grid, r + 1, c, oilCount);
    floodFill(grid, r - 1, c, oilCount);
    floodFill(grid, r, c + 1, oilCount);
    floodFill(grid, r, c - 1, oilCount);
}
