public static int countOilDeposits(char[][] grid) {
    int maxDepth = 0;
    int countDeposits = 0;

    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[i].length; j++) {
            if (grid[i][j] == '*') {
                int depth = dfs(grid, i, j);
                if (depth > 0) {
                    countDeposits++;
                    maxDepth = Math.max(maxDepth, depth);
                }
            }
        }
    }

    return countDeposits;
}

private static int dfs(char[][] grid, int x, int y) {
    if (x < 0 || y < 0 || x >= grid.length || y >= grid[0].length || grid[x][y] != '*') {
        return 0;
    }

    grid[x][y] = '-'; // Mark as visited
    int depth = 1;

    depth += dfs(grid, x + 1, y);
    depth += dfs(grid, x - 1, y);
    depth += dfs(grid, x, y + 1);
    depth += dfs(grid, x, y - 1);

    return depth;
}
