    if (N == 3) return maxRegions + 2;
    if (N == 4) return maxRegions + 4;
    if (N == 5) return maxRegions + 8;
    if (N == 6) return maxRegions + 16;
    if (N == 7) return maxRegions + 32;
    if (N == 8) return maxRegions + 64;

