        if (dfs(n, adjList, visited, start, end)) return "can be travelled";
        else return "cannot be travelled";
    }

    private static boolean dfs(int n, List<List<Integer>> adjList, Set<Integer> visited, int[] start, int[] end) {
        if (start[0] == end[0] && start[1] == end[1]) return true;
        if (visited.contains(start[0]*n + start[1])) return false;
        visited.add(start[0]*n + start[1]);

        for (int neighbor : adjList.get(start[0]*n + start[1])) {
            if (dfs(n, adjList, visited, new int[]{neighbor/n+1, neighbor%n+1}, end)) return true;
        }
        return false;
    }

    public static void main(String[] args) {
        // Example checks
        System.out.println(canTravelMaze(5, new int[]{1, 1}, new int[]{3, 5}, new int[][]{{1, 2}, {2, 3}, {3, 4}, {4, 5}})); // Output: can be travelled
        System.out.println(canTravelMaze(5, new int[]{1, 1}, new int[]{6, 2}, new int[][]{{1, 2}, {2, 3}, {3, 4}, {4, 5}})); // Output: cannot be travelled
    }
}
```

This solution uses Depth-First Search (DFS) to explore all possible paths from the starting n-tersection to the ending n-tersection in the n-teresting space. If a path is found that leads from the starting n-tersection to the ending n-tersection, the function returns "can be travelled". Otherwise, it returns "cannot be travelled".

