private static boolean isVisited(int[] point, int[] target) {
    return point[0] == target[0] && point[1] == target[1];
}

private static boolean dfs(Map<int[], Boolean> visited, int[] current, int[] target, int[][] paths) {
    if (isVisited(current, target)) {
        return true;
    }
    visited.put(current, true);
    for (int[] path : paths) {
        int x = current[0] + path[0];
        int y = current[1] + path[1];
        if (x >= 0 && x < n && y >= 0 && y < n) {
            if (dfs(visited, new int[]{x, y}, target, paths)) {
                return true;
            }
        }
    }
    return false;
}
