private static boolean dfs(int[][] maze, boolean[][] visited, int[] start, int[] end) {
    if (start[0] < 0 || start[0] >= maze.length || start[1] < 0 || start[1] >= maze.length || visited[start[0]][start[1]] || maze[start[0]][start[1]] == 1) {
        return false;
    }
    if (Arrays.equals(start, end)) {
        return true;
    }
    visited[start[0]][start[1]] = true;
    return dfs(maze, visited, new int[]{start[0] + 1, start[1]}, end)
            || dfs(maze, visited, new int[]{start[0], start[1] + 1}, end)
            || dfs(maze, visited, new int[]{start[0] - 1, start[1]}, end)
            || dfs(maze, visited, new int[]{start[0], start[1] - 1}, end);
}
