public boolean canArrange(int[] arr, int k) {
    // Initialize a counter for each possible remainder when divided by k
    int[] remainders = new int[k];
    for (int num : arr) {
        int remainder = num % k;
        remainders[remainder]++;
    }

    // Check if it's possible to pair numbers such that the sum of each pair is divisible by k
    for (int remainder = 0; remainder < k; remainder++) {
        // For remainder 0, count must be even
        if (remainder == 0 && remainder % 2 != 0) {
            return false;
        }
        // For other remainders, pairs must be formed
        if (remainders[remainder] != remainders[k - remainder]) {
            return false;
        }
    }
    return true;
}
