public boolean canArrange(int[] arr, int k) {
    int modFrequency = Arrays.stream(arr).boxed().collect(Collectors.groupingBy(Integer::mod).size());

    for (int i = 1; i <= k / 2; i++) {
        if (modFrequency[i] > modFrequency[k - i]) {
            return false;
        }
    }

    return true;
}
