public int minTime(int n, int[][] edges, boolean[] hasApple) {
    Map<Integer, List<Integer>> graph = new HashMap<>();
    for (int[] e : edges) {
        graph.computeIfAbsent(e[0], k -> new ArrayList<>()).add(e[1]);
        graph.computeIfAbsent(e[1], k -> new ArrayList<>()).add(e[0]);
    }

    boolean[] visited = new boolean[n];
    visited[0] = true;
    int result = 0;

    // Helper function to perform DFS and calculate time
    int dfs(int node) {
        int timeAdded = 1; // Time to collect an apple
        for (int neighbor : graph.get(node)) {
            if (!visited[neighbor]) {
               visited[neighbor] = true;
                timeAdded += dfs(neighbor);

                // Collect an apple, time expected for the tree, multiplying by 2 to account for round trip
                if (hasApple[neighbor] || timeAdded > 1) {
                    result += timeAdded;
                }
            }
        }
        return timeAdded;
    }

    // Start DFS from node 0
    dfs(0);
    return result - 1; // Subtract 1 to exclude the time already taken to go back to node 0
}
