import java.util.HashSet;
import java.util.LinkedList;
import java.util.Map;
import java.util.Set;

class Solution {
    public int minTime(int n, int[][] edges, boolean[] hasApple) {
        Map<Integer, Set<Integer>> graph = new HashMap<>();
        for (int[] edge : edges) {
            graph.computeIfAbsent(edge[0], k -> new HashSet<>()).add(edge[1]);
            graph.computeIfAbsent(edge[1], k -> new HashSet<>()).add(edge[0]);
        }

        Set<Integer> visited = new HashSet<>();
        return minTimeUtil(n, graph, visited, hasApple, 0, 0);
    }

    private int minTimeUtil(int n, Map<Integer, Set<Integer>> graph, Set<Integer> visited, boolean[] hasApple, int currNode, int currTime) {
        if (!hasApple[currNode]) {
            visited.add(currNode);
            for (int neighbor : graph.getOrDefault(currNode, new HashSet<>())) {
                if (!visited.contains(neighbor)) {
                    currTime = minTimeUtil(n, graph, visited, hasApple, neighbor, currTime + 2);
                }
            }
            return currTime;
        } else {
            visited.add(currNode);
            int leftTime = minTimeUtil(n, graph, visited, hasApple, graph.getOrDefault(currNode, new HashSet<>()).iterator().next(), currTime + 2);
            int rightTime = 0;
            if (graph.containsKey(currNode)) {
                for (int neighbor : graph.get(currNode)) {
                    if (visited.contains(neighbor)) continue;
                    rightTime = minTimeUtil(n, graph, visited, hasApple, neighbor, currTime + 2);
                }
            }
            return currTime + Integer.max(0, leftTime + rightTime);
        }
    }
}
