    Arrays.fill(time, 0);
    lastId = 0;

    // Build the tree
    for (int[] e : edges) {
        undirectedEdge(e[0], e[1]);
        undirectedEdge(e[1], e[0]);
    }

    // Traverse the tree to determine the minimum time
    traverse(0, visited, time);

    return Math.max(0, time[0]); // 0 if no apples or including 0 from the start
}

void traverse(int node, boolean[] visited, int[] time) {
    lastId++;
    visited[node] = true;
    time[node] = lastId;

    for (int child : tree[node]) {
        if (!visited[child]) {
            traverse(child, visited, time);
            time[node] = Math.max(time[node], time[child] + 1);
        }
    }
}

void undirectedEdge(int u, int v) {
    tree[u].add(v);
    tree[v].add(u);
}

int lastId = 0;
ArrayList<Integer>[] tree = new ArrayList[n]; // Tree structure where each node has a list of child nodes.
