public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n <= 1) return 0;

    // Initialize adjacency list and visited array
    List<Integer>[] adj = new ArrayList[n];
    boolean[] visited = new boolean[n];
    for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();

    // Build the adjacency list from the given edges
    for (int[] edge : edges) {
        adj[edge[0]].add(edge[1]);
        adj[edge[1]].add(edge[0]);
    }

    // Helper function to traverse and count the time for collecting apples
    return helper(hasApple, 0, adj, visited);
}

// Helper function to traverse recursively and count the time for collecting apples
private int helper(boolean[] hasApple, int root, List<Integer>[] adj, boolean[] visited) {
    visited[root] = true;

    int totalTime = 0;
    // Iterate through the neighbors of the root
    for (int neighbor : adj[root]) {
        if (!visited[neighbor]) {
            int childTime = helper(hasApple, neighbor, adj, visited);
            // If the neighbor has an apple or collects itself, add the time to the total
            if (childTime > 0 || hasApple[neighbor]) {
                totalTime += childTime + 2; // +2 for the time to climb up and back down
            }
        }
    }

    return totalTime;
}
