public String sortString(String s) {
    StringBuilder sorted = new StringBuilder();
    int[] charCount = new int[128]; // ASCII character count array
    boolean[] pickedChar = new boolean[128]; // Array to track picked characters

    // Count occurrences of each character
    for (char c : s.toCharArray()) {
        charCount[c]++;
    }

    // Append characters to sorted in ascending order
    int i = 0;
    while (i < s.length()) {
        for (int c = 0; i < s.length() && charCount[c] > 0; c++) {
            if (!pickedChar[c]) {
                selectedChar(c, sorted, pickedChar);
                charCount[c]--;
                i++;
            }
        }
    }

    // Append characters to sorted in descending order
    for (int i = s.length() - 1; i >= 0 && charCount[i] > 0; i--) {
        for (int c = 127; i >= 0 && charCount[c] > 0; c--) {
            if (!pickedChar[c]) {
                selectedChar(c, sorted, pickedChar);
                charCount[c]--;
                i--;
            }
        }
    }

    return sorted.toString();
}

private void selectedChar(int c, StringBuilder sorted, boolean[] pickedChar) {
    for (int i = 0; i < sorted.length(); i++) {
        if (!pickedChar[sorted.charAt(i)]) {
            sorted.insert(i, (char) c);
            pickedChar[sorted.charAt(i)] = true;
            break;
        }
    }
}
