    int total = Arrays.stream(nums).sum();

    // If the total sum cannot be evenly divided into two parts, return false
    if (total % 2 != 0) {
        return false;
    }

    int target = total / 2;

    // Try all possible divisions for the first half of the array
    for (int i = 1; i <= n / 2; i++) {
        int sumFirstHalf = Arrays.stream(nums).limit(i).sum();
        int sumSecondHalf = total - sumFirstHalf;
        // Check if the second half can also be divided into two equal parts
        if (sumSecondHalf % 2 == 0 && sumSecondHalf / 2 == sumFirstHalf) {
            return true;
        }
    }
    return false;
