        return cost[0]; // Base case: only one step
    }

    int[] dp = new int[cost.length]; // Dynamic programming array
    dp[0] = cost[0];
    dp[1] = Math.min(cost[0], cost[1]); // Base case: only two steps

    for (int i = 2; i < cost.length; i++) {
        dp[i] = Math.min(dp[i-1], dp[i-2]) + cost[i]; // Update minimum cost
    }

    return dp[cost.length-1]; // Return the minimum cost to reach the top
}
