    while (fib[i] <= k) {
        fib[i++] = fib[i - 1] + fib[i - 2];
    }

    int count = 0;
    for (int j = fib.length - 1; j >= 0; j--) {
        while (k >= fib[j]) {
            k -= fib[j];
            count++;
        }
    }

    return count;
}
