        String prefix = s.substring(0, i);
        Set<String> uniqueSubstrings = new HashSet<>();
        uniqueSubstrings.add(prefix);
        int splitIndex = i + 1;

        while (splitIndex <= s.length() && !uniqueSubstrings.contains(s.substring(splitIndex))) {
            uniqueSubstrings.add(s.substring(splitIndex));
            splitIndex++;
