import java.util.ArrayList;
import java.util.List;
import java.util.Stack;

public class SteppingNumberFinder {

    public static List<Integer> findSteppingNumbers(int low, int high) {
        List<Integer> steppingNumbers = new ArrayList<>();
        for (int i = low; i <= high; i++) {
            if (isSteppingNumber(i)) {
                steppingNumbers.add(i);
            }
        }
        steppingNumbers.sort((a, b) -> a - b);
        return steppingNumbers;
    }

    private static boolean isSteppingNumber(int num) {
        if (num < 10) {
            return true;
        }

        String numStr = Integer.toString(num);
        Stack<Character> stack = new Stack<>();
        for (int i = 0; i < numStr.length(); i++) {
            char currentDigit = numStr.charAt(i);
            if (stack.isEmpty() || Math.abs(currentDigit - stack.peek()) == 1) {
                stack.push(currentDigit);
            } else {
                return false;
            }
        }
        return !stack.isEmpty();
    }
}
