public class LongestLine {
    public static int longestLine(int[][] mat) {
        int m = mat.length;
        if (m == 0) return 0;

        int n = mat[0].length;
        if (n == 0) return 0;

        int longest = 1;

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (mat[i][j] == 1) {
                    int length = 1;
                    // Check horizontal
                    for (int k = j + 1; k < n && mat[i][k] == 1; k++) {
                        length++;
                    }
                    for (int k = j + 1; k < n && mat[i][k] == 0; k++) {
                        break;
                    }
                    longest = Math.max(longest, length);

                    // Check vertical
                    for (int k = i + 1; k < m && mat[k][j] == 1; k++) {
                        length++;
                    }
                    for (int k = i + 1; k < m && mat[k][j] == 0; k++) {
                        break;
                    }
                    longest = Math.max(longest, length);

                    // Check diagonal
                    for (int k = 1; i + k < m && j + k < n && mat[i + k][j + k] == 1; k++) {
                        length++;
                    }
                    for (int k = 1; i + k < m && j + k < n && mat[i + k][j + k] == 0; k++) {
                        break;
                    }
                    longest = Math.max(longest, length);

                    // Check anti-diagonal
                    for (int k = 1; i + k < m && j - k >= 0 && mat[i + k][j - k] == 1; k++) {
                        length++;
                    }
                    for (int k = 1; i + k < m && j - k >= 0 && mat[i + k][j - k] == 0; k++) {
                        break;
                    }
                    longest = Math.max(longest, length);
                }
            }
        }

        return longest;
    }
}
