    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            int count = 0;
            while (i < m && j < n && mat[i][j] == 1) {
                count++;
                i++;
                j++;
            }
            longest = Math.max(longest, count);
        }
    }

    // Calculate longest line from the top-right to the bottom-left
    for (int i = 0; i < m; i++) {
        for (int j = n - 1; j >= 0; j--) {
            int count = 0;
            while (i < m && j >= 0 && mat[i][j] == 1) {
                count++;
                i++;
                j--;
            }
            longest = Math.max(longest, count);
        }
    }

    // Calculate longest line from the up-left to the bottom-right
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            int count = 0;
            while (i < m && j < n && mat[i][j] == 1) {
                count++;
                i++;
                j++;
            }
            longest = Math.max(longest, count);
        }
