private static final int[][] directions = new int[][]{{0, 1}, {1, 0}, {1, 1}, {-1, 1}};
private static final int[][] antiDirections = new int[][]{{0, -1}, {1, -1}, {1, -1}, {-1, -1}};

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return 0;
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int maxLength = 0;

    for (int row = 0; row < rows; row++) {
        for (int col = 0; col < cols; col++) {
            if (mat[row][col] == 1) {
                maxLength = Math.max(maxLength, longestLine(mat, row, col, 1, directions));
                maxLength = Math.max(maxLength, longestLine(mat, row, col, 1, antiDirections));
            }
        }
    }

    return maxLength;
}

private static int longestLine(int[][] mat, int row, int col, int length, int[][] directions) {
    for (int direction : directions) {
        int newRow = row + direction[0];
        int newCol = col + direction[1];
        if (newRow >= 0 && newRow < mat.length && newCol >= 0 && newCol < mat[0].length && mat[newRow][newCol] == 1) {
            length++;
        } else {
            return length;
        }
    }
    return length;
}
