    public static int squarePermutations(int[] A) {
        if (A == null || A.length == 0) {
            return 0;
        }

        // Ensure the array has exactly 4 elements
        if (A.length != 4) {
            throw new IllegalArgumentException("Invalid array length. Expected 4 elements.");
        }

        int numPermutations = 0;
        // Generate permutations of the array and check for square pairs
        List<int[]> permutations = generatePermutations(A);
        for (int[] permutation : permutations) {
            if (isSquare(permutation[0]) && isSquare(permutation[1])) {
                if (isSquare(permutation[2]) && isSquare(permutation[3])) {
                    numPermutations++;
                }
            }
        }

        return numPermutations;
    }

    private static List<int[]> generatePermutations(int[] array) {
        List<int[]> permutations = new ArrayList<>();
        permute(array, 0, permutations);
        return permutations;
    }

    private static void permute(int[] array, int start, List<int[]> permutations) {
        if (start == array.length) {
            permutations.add(new int[array.length]);
        } else {
            for (int i = start; i < array.length; i++) {
                swap(array, start, i);
                permute(array, start + 1, permutations);
                swap(array, start, i);
            }
        }
    }

    private static boolean isSquare(int num) {
        long root = (long) Math.sqrt(num);
        return root * root == num;
    }

    private static void swap(int[] array, int i, int j) {
        int temp = array[i];
        array[i] = array[j];
        array[j] = temp;
    }
}
