import java.util.Arrays;
import java.util.HashSet;

public static int squarePermutations(int[] A) {
    // We use a set for quick lookup to check if a number is a perfect square
    HashSet<Integer> squares = new HashSet<>();
    for (int i = 1; i * i <= 100000; i++) {
        squares.add(i * i);
    }

    // Helper function to recursively calculate permutations
    int[] n = A.clone();
    int count = 0;
    boolean[] used = new boolean[n.length];
    count = recursivePermute(n, 0, count, used, squares);
    return count;
}

private static int recursivePermute(int[] n, int start, int count, boolean[] used, HashSet<Integer> squares) {
    if (start == n.length) {
        // Check if the current permutation forms a square array
        for (int i = 1; i < n.length; i++) {
            if (!squares.contains(n[i - 1] + n[i])) {
                return 0;
            }
        }
        return 1;
    }

    for (int i = start; i < n.length; i++) {
        if (used[i]) {
            continue;
        }
        used[i] = true;
        int[] temp = new int[n.length];
        System.arraycopy(n, 0, temp, 0, n.length);
        temp[start] = n[i];
        temp[i] = n[start];
        count += recursivePermute(temp, start + 1, count, used, squares);
        used[i] = false;
    }
    return count;
}
