public static int findSmallestInteger(int n) {
    char[] digits = String.valueOf(n).toCharArray();
    int idx = -1;

    // Find the first digit that is smaller than the digit immediately following it
    for (int i = digits.length - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            idx = i;
            break;
        }
    }

    if (idx == -1) {
        return -1; // No such rearrangement exists
    }

    // Find the smallest digit greater than digits[idx] to swap with
    for (int j = digits.length - 1; j >= idx; j--) {
        if (digits[j] > digits[idx]) {
            swap(digits, idx, j);
            break;
        }
    }

    // Reverse the digits from idx+1 to the end
    reverse(digits, idx + 1, digits.length - 1);

    return Integer.parseInt(new String(digits));
}

private static void swap(char[] arr, int i, int j) {
    char temp = arr[i];
    arr[i] = arr[j];
    arr[j] = temp;
}

private static void reverse(char[] arr, int start, int end) {
    while (start < end) {
        swap(arr, start, end);
        start++;
        end--;
    }
}
