public static boolean isBoomerang(int[][] points) {
    int len = points.length;

    // Check if the points are not collinear
    if (isColinear(points)) {
        return false; // If they are collinear, the points do not form a boomerang
    }

    int area = 0;

    // Calculate the area using the determinant method
    for (int i = 0; i < len; i++) {
        int j = (i+1) % len;
        area += points[i][0] * points[j][1] - points[i][1] * points[j][0];
    }

    return Math.abs(area) != 0; // A non-zero area indicates the points form a boomerang
}

// Helper method to check if three points are collinear
private static boolean isColinear(int[][] points) {
    int len = points.length;
    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];
    int determinant = x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2);
    return Math.abs(determinant) < 0.00001; // A small threshold for floating-point comparison
}
