    int centerX = (points[0][0] + points[1][0] + points[2][0]) / 3;
    int centerY = (points[0][1] + points[1][1] + points[2][1]) / 3;

    // Calculate the slopes of the opposite sides of the triangle
    double slope1 = (points[1][1] - centerY) / (points[1][0] - centerX);
    double slope2 = (points[2][1] - centerY) / (points[2][0] - centerX);
    double slope3 = (points[0][1] - centerY) / (points[0][0] - centerX);

    // Check if the slopes are distinct
    return slope1 != slope2 && slope2 != slope3;
