        return 0;
    }

    int maxEnergy = 0;
    int currentEnergy = 1;
    char prevChar = s.charAt(0);

    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == prevChar) {
            currentEnergy++;
        } else {
            prevChar = s.charAt(i);
            maxEnergy = Math.max(maxEnergy, currentEnergy);
            currentEnergy = 1;
        }
    }

    maxEnergy = Math.max(maxEnergy, currentEnergy);
    return maxEnergy;
