import java.util.List;

public class LexicalOrder {
    public static List<Integer> lexicalOrder(int n) {
        List<Integer> result = new ArrayList<>();
        generateOrder(result, n);
        Collections.sort(result);
        return result;
    }

    private static void generateOrder(List<Integer> result, int n) {
        if (n == 0) {
            result.add(0);
            return;
        }
        for (int i = 1; i <= 9 && i <= n; i++) {
            result.add(i);
            generateOrder(result, n - i);
        }
    }

    public static void main(String[] args) {
        List<Integer> sortedOrder = lexicalOrder(13);
        System.out.println(sortedOrder); // Output: [1, 10, 11, 12, 13, 2, 3, 4, 5, 6, 7, 8, 9]
    }
}
