public static int minPerfectSquareSum(int n) {
    // Create a set of all perfect squares up to sqrt(n) * sqrt(n)
    Set<Integer> perfectSquares = new HashSet<>();
    for (int i = 1; i <= Math.sqrt(n); i++) {
        perfectSquares.add(i * i);
    }
    return minPerfectSquareSumNico(n, perfectSquares);
}

private static int minPerfectSquareSumNico(int target, Set<Integer> perfectSquares) {
    if (target == 0) {
        return 0;
    }
    // Try all perfect squares less than or equal to the target
    for (int square : perfectSquares) {
        if (square <= target) {
            // Recursively find the shortest sum for the remaining value
            int sum = 1 + minPerfectSquareSumNico(target - square, perfectSquares);
            // Update the minimum sum found
            if (sum < minPerfectSquareSum) {
                minPerfectSquareSum = sum;
            }
        }
    }
    return minPerfectSquareSum;
}
