public static String reverseWords(String s) {
    char[] chars = s.toCharArray();
    int i = 0, j = 0;
    while (j < chars.length) {
        char c = chars[j];
        if (c == ' ') {
            reverse(chars, i, j - 1);
            i = j + 1;
        }
        j++;
    }
    reverse(chars, i, j - 1);
    return new String(chars);
}

private static void reverse(char[] chars, int low, int high) {
    while (low < high) {
        char temp = chars[low];
        chars[low] = chars[high];
        chars[high] = temp;
        low++;
        high--;
    }
}
